library(shiny)
library(leaflet)
library(terra)
library(rgbif)
library(sf)
library(rnaturalearth)
library(rnaturalearthdata)
library(wesanderson)
library(shiny.fluent)

# -------------------------------------------------------------------------
# Data and configuration
# -------------------------------------------------------------------------


species_list <- c(
  "Dendroctonus ponderosae",
  "Agrilus planipennis",
  "Thaumetopoea processionea"
)

species_common_names <- c(
  "Dendroctonus ponderosae" = "Mountain pine beetle",
  "Agrilus planipennis" = "Emerald ash borer",
  "Thaumetopoea processionea" = "Oak processionary moth"
)

# Confirmed beta model specification; occupied cells are training cells,
# not the changing count of live GBIF records displayed on the map.
beta_model_specs <- list(
  "Agrilus planipennis" = list(cells = "2,131", predictors = c("BIO6", "BIO10"), features = "Linear + quadratic (LQ)"),
  "Thaumetopoea processionea" = list(cells = "2,383", predictors = c("BIO5", "BIO6", "BIO16", "BIO17"), features = "Linear + quadratic (LQ)"),
  "Dendroctonus ponderosae" = list(cells = "26", predictors = c("BIO6", "BIO10"), features = "Linear (L)")
)
bio_definitions <- c(
  BIO5 = "Maximum temperature of the warmest month",
  BIO6 = "Minimum temperature of the coldest month",
  BIO10 = "Mean temperature of the warmest quarter",
  BIO16 = "Precipitation of the wettest quarter",
  BIO17 = "Precipitation of the driest quarter"
)

species_descriptions <- c(
  "Dendroctonus ponderosae" =
    "A major bark beetle of pine forests in western North America.",

  "Agrilus planipennis" =
    "An invasive wood-boring beetle responsible for extensive ash mortality.",

  "Thaumetopoea processionea" =
    "A defoliating moth of oak whose caterpillars have urticating hairs."
)

gbif_taxon_keys <- c(
  "Dendroctonus ponderosae" = 1228026,
  "Agrilus planipennis" = 5878492,
  "Thaumetopoea processionea" = 1824113
)


# Keep a models/ folder beside the app for deployment. An environment
# variable can point to a different folder during local development.

catalogue <- read.csv(
  "data/model_catalogue.csv",
  stringsAsFactors = FALSE,
  check.names = FALSE
)
stopifnot(
  !anyDuplicated(catalogue$model_id),
  all(file.exists(catalogue$file))
)
suitability_rasters <- setNames(
  lapply(catalogue$file, terra::rast),
  catalogue$model_id
)

