display_raster_cache <- new.env(parent = emptyenv())
masked_display_raster <- function(model_id) {
  if (exists(model_id, envir = display_raster_cache, inherits = FALSE)) {
    return(get(model_id, envir = display_raster_cache, inherits = FALSE))
  }
  original <- suitability_rasters[[model_id]]
  # Subdivide only for shoreline display; replicate values without interpolation.
  # This adds no climate information and never changes the source files.
  display <- terra::disagg(original, fact = 4, method = "near")
  lakes <- terra::project(inland_water, terra::crs(display))
  display <- terra::mask(display, lakes, inverse = TRUE, touches = FALSE)
  assign(model_id, display, envir = display_raster_cache)
  display
}

