europe_country_codes <- unique(c(
  eu_country_codes, "AL", "AD", "BA", "BY", "CH", "GB", "IS", "LI",
  "MD", "ME", "MK", "NO", "RS", "RU", "TR", "UA", "XK"
))
# Bound the regional search to Europe; exclude overseas territories and Asian Russia.
# This is an operational viewing region, not a precise continental boundary.
europe_geometry <- "POLYGON((-25 34,60 34,60 72,-25 72,-25 34))"

# Use human field observations only: no specimens, cultures, or machine records.
