photo_credit <- function(photo) {
  tags$figcaption(class = "photo-credit",
    paste0("Photo: ", photo$credit, ". "),
    tags$a(href = photo$source, target = "_blank", rel = "noopener noreferrer", "Source"),
    " · ", tags$a(href = photo$license_url, target = "_blank", rel = "noopener noreferrer", photo$license),
    "."
  )
}

