info_dialog <- function(id, title, ...) {
  tags$dialog(id = id, class = "info-dialog", `aria-label` = title,
    tags$button(type = "button", class = "photo-button dialog-close", autofocus = NA,
      onclick = "this.closest('dialog').close();", "Close"),
    tags$h2(title), ...)
}
# Build documentation with the page, independent of Shiny input/output bindings.
model_documentation <- function(species) {
  spec <- beta_model_specs[[species]]
  row <- function(label, value) tags$tr(tags$th(scope = "row", label), tags$td(value))
  background <- "200 km and 500 km variants"
    tagList(
      tags$h4(species_common_names[[species]]),
      tags$table(class = "model-specs",
        tags$tbody(
          row("Occupied training cells", spec$cells),
          row("Predictors", paste(spec$predictors, collapse = ", ")),
          row("Method", "MaxEnt"),
          row("Features", spec$features),
          row("Regularization multiplier", "1"),
          row("Background", background),
          row("Training climate", "2001–2020 · provisional CRU-derived baseline"),
          row("Climate grid", "2.5 arc minutes"))),
      p(class = "small-note", "Training-cell counts describe the fitted models. They are separate from live GBIF record counts."),
      tags$details(tags$summary("Predictor definitions"),
        tags$ul(lapply(spec$predictors, function(code) tags$li(strong(paste0(code, ": ")), bio_definitions[[code]])))),
      tags$h4("Evidence and limitations"),
      p("These models describe associations between recorded occurrences and climate. They do not estimate arrival, establishment or damage probabilities. Host availability, dispersal and management are not modelled."),
      if (base::identical(species, "Dendroctonus ponderosae"))
        p("The MPB model is exploratory: only 26 occupied training cells were available, with weak performance in some held-out regions. Broadly elevated scores do not establish high risk across Sweden.")
      else p("Suitability outside the training region is a model projection. Predictive accuracy in Sweden has not been established."),
      p("The studies listed under Scientific references informed the modelling context and predictor choices; they do not validate the InvaSkog predictions."))
}

