)

ui <- fluentPage(
  tags$head(
    tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"),
    tags$script(HTML("$(document).on('shiny:connected', function() {
      Shiny.addCustomMessageHandler('suitability-opacity', function(value) {
        var widget = HTMLWidgets.find('#map');
        if (!widget || !widget.getMap) return;
        var map = widget.getMap();
        var layer = map.layerManager.getLayer('image', 'suitability-raster');
        if (layer && typeof layer.setOpacity === 'function') layer.setOpacity(value);
      });
    });")),
    tags$script(HTML("$(function() {
      var container = document.querySelector('.map-container');
      var panel = document.querySelector('.options-overlay');
      if (!container || !panel) return;
      function fitOptions() {
        var legend = container.querySelector('.info.legend');
        var bottom = container.getBoundingClientRect().bottom - 28;
        if (legend) bottom = Math.min(bottom, legend.getBoundingClientRect().top - 12);
        var available = Math.max(48, bottom - panel.getBoundingClientRect().top);
        panel.style.maxHeight = available + 'px';
        var content = panel.querySelector('.panel-content');
        var summary = panel.querySelector('summary');
        if (content && summary && panel.open) {
          content.style.maxHeight = Math.max(0, available - summary.getBoundingClientRect().height - 2) + 'px';
        }
      }
      function fitLeftPanels() {
        var species = container.querySelector('.species-overlay');
        var reading = container.querySelector('.reading-overlay');
        if (!species || !reading) return;
        var details = species.querySelector('details');
        var speciesSummary = details && details.querySelector('summary');
        var speciesContent = species.querySelector('.species-expanded');
        var readingSummary = reading.querySelector('summary');
        var readingContent = reading.querySelector('.panel-content');
        if (!speciesSummary || !speciesContent || !readingSummary || !readingContent) return;
        var top = species.getBoundingClientRect().top;
        var bottom = reading.getBoundingClientRect().bottom;
        var total = Math.max(0, bottom - top - 12);
        var speciesHeader = speciesSummary.getBoundingClientRect().height + 2;
        var readingHeader = readingSummary.getBoundingClientRect().height + 2;
        // Reserve both headers, then share the remaining height when both are open.
        var bodySpace = Math.max(0, total - speciesHeader - readingHeader);
        var readingLimit = details.open ? bodySpace * 0.45 : bodySpace;
        readingContent.style.maxHeight = readingLimit + 'px';
        var readingHeight = reading.getBoundingClientRect().height;
        var speciesLimit = Math.max(0, total - readingHeight - speciesHeader);
        speciesContent.style.maxHeight = speciesLimit + 'px';
      }
      var leftResize = new ResizeObserver(fitLeftPanels);
      leftResize.observe(container);
      leftResize.observe(container.querySelector('.reading-overlay'));
      leftResize.observe(container.querySelector('.species-overlay'));
      var leftMutation = new MutationObserver(fitLeftPanels);
      leftMutation.observe(container.querySelector('.species-overlay'), {childList:true, subtree:true});
      leftMutation.observe(container.querySelector('.reading-overlay'), {childList:true, subtree:true});
      container.addEventListener('toggle', fitLeftPanels, true);
      window.addEventListener('resize', fitLeftPanels);
      fitLeftPanels();
      var resize = new ResizeObserver(fitOptions);
      resize.observe(container);
      var mutation = new MutationObserver(function() {
        var legend = container.querySelector('.info.legend');
        if (legend) resize.observe(legend);
        fitOptions();
      });
      mutation.observe(document.getElementById('map'), {childList:true, subtree:true});
      panel.addEventListener('toggle', fitOptions);
      window.addEventListener('resize', fitOptions);
      fitOptions();
    });")),
    tags$style(HTML("

.marker-cluster-small,.marker-cluster-medium,.marker-cluster-large {background:rgba(167,139,212,.35)!important;}
.marker-cluster-small div,.marker-cluster-medium div,.marker-cluster-large div {background:#A78BD4!important;color:#241533!important;border:1px solid #4D326F;font-weight:700;}
.options-overlay[open] {overflow:hidden;}
.options-overlay > summary {flex-shrink:0;}
.options-overlay > .panel-content {min-height:0;overflow-y:scroll;overscroll-behavior:contain;scrollbar-gutter:stable;scrollbar-width:auto;scrollbar-color:#789681 #EDF2EB;}
.options-overlay > .panel-content::-webkit-scrollbar {width:12px;}
.options-overlay > .panel-content::-webkit-scrollbar-track {background:#EDF2EB;border-radius:8px;}
.options-overlay > .panel-content::-webkit-scrollbar-thumb {background:#789681;border:3px solid #EDF2EB;border-radius:8px;}
.options-overlay > .panel-content::-webkit-scrollbar-thumb:hover {background:#193F35;}
html, body, .ms-Fabric {width:100%;height:100%;margin:0;color:#202924;font-family:'Segoe UI',Arial,sans-serif;background:#F7F8FA;}
* {box-sizing:border-box;} body {overflow:hidden;}
.app-shell {height:100vh;height:100dvh;display:flex;flex-direction:column;}
.top-bar {display:flex;align-items:center;justify-content:space-between;min-height:60px;padding:6px 24px;background:white;border-bottom:1px solid #E2E7E4;gap:12px;}
.brand-group,.header-actions {display:flex;align-items:center;gap:12px;}
.brand-logo {width:48px;height:48px;object-fit:contain;}
h1 {font-size:25px;font-weight:650;margin:0;letter-spacing:-.6px;}
.beta-badge {background:#F0EBF8;color:#634497;border-radius:8px;padding:5px 10px;font-size:12px;font-weight:600;}
.btn {border-radius:7px;min-height:36px;box-shadow:none;}
.text-button {border:0;background:transparent;color:#064E3B;padding:6px 10px;}
.text-button:hover {background:#EDF2EB;color:#064E3B;}
.selection-strip {display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:10px 24px;background:white;border-bottom:1px solid #E2E7E4;z-index:1001;}
.selector {display:flex;align-items:center;gap:12px;}
.selector > div {width:230px;}
.sentence-word {font-size:14px;}
.ms-Dropdown-label {position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);}
.ms-Dropdown-title {background:#EDF2EB!important;border:1px solid #D3DFCF!important;border-radius:7px;height:38px;line-height:36px;color:#202924;}
.ms-Dropdown-caretDownWrapper {height:38px;line-height:38px;}
.ms-Dropdown:focus::after {border-color:#634497!important;}
.form-group {margin-bottom:0;} .form-control {border:1px solid #A8BBA5;border-radius:7px;color:#202924;box-shadow:none;}
#model_controls .form-group {width:260px;} #model_controls label {font-size:11px;margin:0;color:#626B67;}
.refresh-button {background:#fff;color:#064E3B;border:1px solid #064E3B;padding:6px 12px;}
.refresh-button:hover {background:#EDF2EB;color:#064E3B;}
.map-container {position:relative;flex:1;min-height:180px;isolation:isolate;}
#map {width:100%!important;height:100%!important;}
.map-card {position:absolute;z-index:700;background:white;border:1px solid #E2E7E4;border-radius:9px;box-shadow:0 2px 10px #19352D18;font-size:13px;}
.species-overlay {top:16px;left:16px;width:280px;}
summary {cursor:pointer;padding:12px 15px;font-weight:600;color:#064E3B;}
summary:hover {background:#EDF2EB;border-radius:8px;}
summary:focus-visible,button:focus-visible,a:focus-visible {outline:3px solid #8060B1!important;outline-offset:3px;}
.species-common-name {font-size:15px;font-weight:650;color:#202924;}
.species-scientific-name {font-size:12px;font-style:italic;color:#626B67;margin-top:3px;}
.species-description {padding:0 15px 14px;margin:0;line-height:1.5;}
.options-overlay {right:16px;top:92px;max-width:280px;}
.options-overlay[open] {width:280px;}
.panel-content {padding:0 15px 14px;max-height:45vh;overflow:auto;line-height:1.55;}
.panel-content p {margin:10px 0;} .research-panel {margin-top:12px;background:#EDF2EB;border-radius:7px;padding:0 8px 8px;}
.research-panel summary {padding-left:0;} .research-panel .form-group {margin-top:8px;}
.reading-overlay {left:16px;bottom:44px;max-width:380px;background:#EDF2EB;}
.reading-overlay > .panel-content {box-sizing:border-box;min-height:0;overscroll-behavior:contain;scrollbar-gutter:stable;scrollbar-color:#789681 #EDF2EB;}
.reading-overlay[open] {width:380px;max-width:calc(100% - 32px);}
.source-note {font-size:12px;line-height:1.55;} .source-note strong {color:#064E3B;}
.small-note {font-size:11px;color:#626B67;}
.map-status {position:absolute;z-index:650;left:50%;bottom:12px;transform:translateX(-50%);background:#fffffff5;border:1px solid #E2E7E4;border-radius:7px;padding:7px 12px;max-width:45%;font-size:11px;line-height:1.4;}
.map-status strong {display:block;color:#064E3B;}.evidence-note {display:block;margin-top:3px;}
.app-footer {display:flex;justify-content:space-between;padding:7px 24px;background:white;border-top:1px solid #E2E7E4;font-size:11px;color:#626B67;}
.leaflet-top.leaflet-left {left:auto;right:16px;}.leaflet-top.leaflet-left .leaflet-control {float:right;margin-right:0;margin-left:0;}
.leaflet-control-zoom,.info.legend {border:0!important;border-radius:8px!important;box-shadow:0 2px 10px #19352D22!important;}
.info.legend {background:#fffffff5;padding:10px 12px;font-size:11px;line-height:18px;max-width:220px;}
.legend-title {display:block;font-weight:650;}.popup-species {font-style:italic;font-weight:600;}
.shiny-busy .map-container::after {content:'Loading map data…';position:absolute;z-index:900;left:50%;top:50%;transform:translate(-50%,-50%);background:white;padding:12px 20px;border-radius:8px;color:#064E3B;box-shadow:0 2px 12px #19352D22;}
@media(max-width:900px){.selection-strip {gap:8px;padding:8px 14px;}.selector > div {width:205px;}.top-bar{padding:6px 14px;}.map-status{max-width:42%;}.header-actions{gap:0;}}
@media(max-width:600px){.top-bar{min-height:52px;padding:4px 10px;}.brand-logo{width:36px;height:36px;}.brand-group{gap:7px;}h1{font-size:20px;}.text-button{font-size:11px;padding:4px 6px;}.beta-badge{padding:4px 6px;}.selection-strip{padding:7px 10px;gap:6px;}.selector{flex:1;min-width:140px;}.selector > div{width:100%;}.sentence-word{display:none;}#model_controls .form-group{width:210px;}.refresh-button{font-size:12px;}.species-overlay{top:10px;left:10px;width:220px;}.species-common-name{font-size:13px;}.species-scientific-name{font-size:11px;}summary{padding:10px;}.options-overlay{right:10px;top:90px;}.reading-overlay{left:10px;bottom:125px;max-width:250px;}.panel-content{max-height:30vh;}.map-status{left:10px;transform:none;bottom:30px;max-width:calc(100% - 180px);font-size:10px;}.info.legend{max-width:155px;font-size:10px;padding:8px;}.app-footer{padding:6px 10px;font-size:10px;}.app-footer span:last-child{display:none;}}

