.species-overlay .species-scientific-name {color:#D4E2D0;}
.species-expanded {box-sizing:border-box;min-height:0;overscroll-behavior:contain;scrollbar-gutter:stable;scrollbar-color:#A6BBA2 #193F35;padding:0 15px 15px;max-height:calc(100dvh - 330px);overflow-y:auto;}
.adult-label {font-size:10px;letter-spacing:.12em;font-weight:700;color:#D4E2D0;}
.adult-figure {margin:8px 0 12px;}
.adult-photo {display:block;width:100%;height:210px;object-fit:contain;background:#F7F8FA;border-radius:6px;}
.photo-credit {font-size:10px;line-height:1.5;margin-top:8px;}
.species-overlay .photo-credit {color:#D4E2D0;}
.species-overlay a {color:#E5D8FF;text-decoration:underline;}
.photo-button {background:#EDF2EB;color:#193F35;border:0;padding:6px 12px;border-radius:6px;}
.species-overlay .species-description {padding:12px 0 0;color:#F5F8F3;}
.photo-guidance {font-size:11px;line-height:1.5;margin:10px 0 0;color:#D4E2D0;}
@media(max-width:600px){.species-overlay{width:250px;}.adult-photo{height:160px;}.species-expanded{max-height:35vh;}}
.photo-dialog {border:0;border-radius:12px;background:#fff;color:#202924;padding:22px;width:min(850px,92vw);max-height:90dvh;overflow:auto;box-shadow:0 12px 50px #0005;}
.photo-dialog::backdrop {background:rgba(12,29,24,.72);}
.photo-dialog h2 {font-size:20px;margin:0 70px 15px 0;}
.photo-dialog figure {margin:0;}
.enlarged-photo {display:block;width:100%;height:65vh;object-fit:contain;}
.dialog-close {float:right;cursor:pointer;}
.species-overlay .photo-dialog .photo-credit {color:#505B55;}
.species-overlay .photo-dialog a {color:#5B3B86;}
.eppo-link {display:block;margin-top:14px;font-size:13px;line-height:1.5;font-weight:600;}

.info-dialog {border:0;border-radius:12px;width:min(760px,94vw);max-height:88dvh;overflow:auto;padding:28px;background:#FFFFFF;color:#202924;font:14px/1.65 'Segoe UI',Arial,sans-serif;}
.info-dialog::backdrop {background:rgba(12,29,24,.7);}
.info-dialog h2{font-size:26px;margin:0 70px 16px 0;color:#193F35;}
.model-specs {width:100%;border-collapse:collapse;font-size:13px;}
.model-specs th,.model-specs td {padding:8px;text-align:left;vertical-align:top;border-bottom:1px solid #E2E7E4;}
