      ),
      tags$details(class = "map-card reading-overlay",
        tags$summary("How to read this map"),
        div(class = "panel-content", tabindex = "0", role = "region", `aria-label` = "Map reading guidance",
          conditionalPanel("input.view_selector === 'occurrence'", uiOutput("observation_note")),
          conditionalPanel("input.view_selector === 'model'", uiOutput("model_details")),
          p(class = "small-note", "Data sources: GBIF human observations; InvaSkog MaxEnt models.")
        )
      ),
      uiOutput("map_status")
    ),
    tags$footer(class = "app-footer",
      div(class = "support-credit",
        tags$img(src = lnu_logo, alt = "Linnéuniversitetet", class = "lnu-footer-logo")),
      span("InvaSkog · Beta")),
    help_page, about_page
  )
)

# -------------------------------------------------------------------------
# Server
# -------------------------------------------------------------------------

server <- function(input, output, session) {
  
  selected_species <- reactive({
    req(input$pest_selector)
    input$pest_selector
  })
  
  selected_view <- reactive({
    req(input$view_selector)
    input$view_selector
  })
  

  output$model_controls <- renderUI({
    rows <- catalogue[catalogue$species == selected_species(), , drop = FALSE]
    if (!nrow(rows)) return(div("Model not yet packaged"))
    labels <- c(baseline = "Baseline: 2001–2020",
                future = "Future: 2041–2060 · SSP2-4.5",
                future_spread = "Future climate-model disagreement")
    available <- unique(rows$period_key)
    selectInput("climate_period", "Climate period / layer",
      choices = setNames(available, unname(labels[available])), selected = "baseline")
  })

  observeEvent(input$locate_stand, {
    lat <- input$stand_lat
    lon <- input$stand_lon
    if (is.null(lat) || is.null(lon) || !is.finite(lat) || !is.finite(lon) ||
        abs(lat) > 90 || abs(lon) > 180) {
      showNotification("Enter valid latitude and longitude in decimal degrees.", type = "error")
      return()
    }
    leafletProxy("map") %>% clearGroup("Selected location") %>%
      addMarkers(lng = lon, lat = lat, group = "Selected location",
                 popup = "Selected location — not a stand boundary") %>%
      setView(lng = lon, lat = lat, zoom = 12)
  })
  # Change rendered image opacity without reprojecting the raster or resetting the view.
  observeEvent(input$suitability_opacity, {
    session$sendCustomMessage("suitability-opacity", input$suitability_opacity / 100)
  })

  observeEvent(input$reset_sweden, {
    leafletProxy("map") %>% fitBounds(10.5, 55.0, 24.5, 69.5)
  })
  selected_model <- reactive({
    if (!base::identical(input$view_selector, "model")) return(NULL)
    rows <- catalogue[catalogue$species == selected_species(), , drop = FALSE]
    if (!nrow(rows)) return(NULL)
    if (is.null(input$climate_period) || is.null(input$background_choice)) return(NULL)
    rows <- rows[
      rows$period_key == input$climate_period &
      as.character(rows$buffer_km) == input$background_choice,
      , drop = FALSE
    ]
    if (nrow(rows) != 1) return(NULL)
    rows
  })

  output$model_details <- renderUI({
    model <- selected_model()
    if (is.null(model)) return(p("Choose a climate layer to see its map key."))
    spread <- base::identical(model$period_key[[1]], "future_spread")
    div(class = "source-note",
      strong(if (spread) "Climate-model disagreement" else "Climate suitability"),
      p(model$description),
      p(if (spread) "Darker blue means greater disagreement between the three climate models."
        else "Darker burgundy means higher modelled climate suitability. The legend uses a fixed 0–1 scale."),
      p("Use the opacity slider to reveal the satellite imagery."))
  })


  last_observation_refresh <- 0L
  pest_data <- reactive({
    refresh_click <- input$refresh_observations
    force_refresh <- !is.null(refresh_click) && refresh_click > last_observation_refresh
    if (force_refresh) last_observation_refresh <<- refresh_click
    species <- selected_species()
    policy <- observation_policies[[species]]
    current_year <- as.integer(format(Sys.Date(), "%Y"))
    years <- if (is.null(policy$years)) NULL else
      seq.int(current_year - policy$years + 1L, current_year)
    taxon_key <- unname(gbif_taxon_keys[species])

    tryCatch({
      withProgress(message = "Loading GBIF human observations", value = 0, {
        context <- fetch_recent_records(
          taxon_key, years, observation_limit, policy$countries, policy$geometry,
          force_refresh = force_refresh,
          progress = function(value, count) setProgress(value, detail =
            sprintf("%s records received", format(count, big.mark = ",")))
        )
        observations <- context$data
        total <- context$total
        excluded_count <- if ("key" %in% names(observations)) {
          sum(as.character(observations$key) %in% policy$exclude_gbif_keys)
        } else 0L
        if (excluded_count > 0L && "key" %in% names(observations)) {
          observations <- observations[
            !as.character(observations$key) %in% policy$exclude_gbif_keys,
            , drop = FALSE
          ]
        }
        setProgress(1)
        list(
          data = observations, total = total,
          partial = context$partial, stale = context$stale, retrieved_at = context$cached_at,
          display_total = max(0, total - excluded_count),
          excluded_count = excluded_count,
          period = if (is.null(years)) "all years" else
            sprintf("%s–%s", min(years), max(years)),
          scope = policy$scope, global = policy$global,
          capped = total > nrow(observations),
          error = FALSE, error_message = NULL
        )
      })
    }, error = function(e) {
      message("GBIF retrieval failed for ", species, ": ", conditionMessage(e))
      list(
        data = data.frame(), total = NA_integer_,
        display_total = NA_integer_, excluded_count = 0L,
        period = if (is.null(years)) "all years" else
          sprintf("%s–%s", min(years), max(years)),
        scope = policy$scope, global = policy$global,
        error = TRUE, error_message = conditionMessage(e)
      )
    })
  })

  observation_summary <- reactive({
    gbif <- pest_data()
    if (isTRUE(gbif$error)) {
      return(paste("GBIF observations could not be retrieved:", gbif$error_message,
                   "Use Refresh records to retry."))
    }
    counts <- sprintf(
      "%s: showing %s of %s matching human observations.",
      gbif$scope, format(nrow(gbif$data), big.mark = ","),
      format(gbif$display_total, big.mark = ",")
    )
    excluded_note <- if (gbif$excluded_count > 0L) {
      sprintf("%s unverified source record excluded after review.", gbif$excluded_count)
    } else ""
    cap_note <- if (gbif$display_total > nrow(gbif$data)) {
      "A subset is displayed; the display limit and record filtering can reduce the number shown."
    } else "All matching records are shown."
    paste(counts, excluded_note, cap_note,
          "Record density reflects reporting effort, not pest abundance or absence.")
  })

  output$observation_note <- renderUI({
    if (!base::identical(input$view_selector, "occurrence")) return(NULL)
    gbif <- pest_data()
    if (isTRUE(gbif$error)) return(p("Observations unavailable. Use Refresh records to retry."))
    div(class = "source-note", strong(gbif$scope),
      p(sprintf("Showing %s of %s matching human observations.",
                format(nrow(gbif$data), big.mark = ","), format(gbif$display_total, big.mark = ","))),
      if (gbif$display_total > nrow(gbif$data))
        p("Browsing subset, not a representative sample. Up to 3,000 records are displayed."),
      if (isTRUE(gbif$partial)) p("GBIF retrieval stopped early; available records are shown."),
      if (isTRUE(gbif$stale)) p("Refresh incomplete; previously retrieved records are shown."),
      p(paste("Retrieved:", format(gbif$retrieved_at, "%Y-%m-%d %H:%M UTC", tz = "UTC"))),
      p("Numbers inside circles count grouped records. Zoom in and select a point to view its GBIF record."))
  })

  eppo_codes <- c("Agrilus planipennis" = "AGRLPL",
                  "Thaumetopoea processionea" = "THAUPR",
                  "Dendroctonus ponderosae" = "DENCPO")
  output$species_card <- renderUI({
    species <- selected_species()
    photo <- species_photos[[species]]
    tags$details(open = TRUE,
      tags$summary(
        div(class = "species-common-name", species_common_names[[species]]),
        div(class = "species-scientific-name", species)),
      div(class = "species-expanded", tabindex = "0", role = "region", `aria-label` = "Species information",
        span(class = "adult-label", "ADULT"),
        tags$figure(class = "adult-figure",
          tags$img(src = photo$src, alt = paste("Adult", species_common_names[[species]], "—", species),
                   class = "adult-photo"),
          photo_credit(photo)),
        tags$button(type = "button", class = "photo-button",
          onclick = "this.parentElement.querySelector('dialog').showModal();", "Enlarge photo"),
        tags$dialog(class = "photo-dialog", `aria-label` = paste("Adult", species),
          tags$button(type = "button", class = "photo-button dialog-close", autofocus = NA,
            onclick = "this.closest('dialog').close();", "Close"),
          tags$h2(paste(species_common_names[[species]], "— adult")),
          tags$figure(tags$img(src = photo$src, alt = paste("Adult", species),
            class = "enlarged-photo"), photo_credit(photo))
        ),
        p(class = "species-description", species_descriptions[[species]]),
        tags$a(class = "eppo-link", href = paste0("https://gd.eppo.int/taxon/", eppo_codes[[species]]),
          target = "_blank", rel = "noopener noreferrer", "Species information & photos — EPPO ↗"),
        p(class = "photo-guidance", "For identification support, explore the EPPO species information and photographs.")
      )
    )
  })
  output$map_status <- renderUI({
    if (base::identical(input$view_selector, "occurrence")) {
      gbif <- pest_data()
      if (isTRUE(gbif$error)) return(div(class = "map-status", role = "status",
        strong("Observations unavailable"), "Use Refresh records to retry."))
      div(class = "map-status", role = "status",
        strong(paste(format(nrow(gbif$data), big.mark = ","), "human observations")),
        gbif$scope, " · Reporting effort varies.")
    } else {
      NULL
    }
  })

  # Base map is rendered only once.
  output$map <- renderLeaflet({
    
    leaflet(
      options = leafletOptions(
        zoomControl = TRUE,
        minZoom = 1,
        maxZoom = 13
      )
    ) %>%
      
      # ESRI imagery provides useful landscape context for forest users.
      addProviderTiles(
        providers$Esri.WorldImagery,
        group = "Satellite"
      ) %>%
      
      fitBounds(
        lng1 = 10.5,
        lat1 = 55.0,
        lng2 = 24.5,
        lat2 = 69.5
      ) %>%
      
      addScaleBar(
        position = "bottomleft",
        options = scaleBarOptions(
          metric = TRUE,
          imperial = FALSE
        )
      )
  })
  
  observeEvent(
    list(
      selected_species(),
      selected_view(),
      input$refresh_observations,
      input$climate_period,
      input$background_choice
    ),
    {
      
      species <- selected_species()
      view <- selected_view()
      model <- if (base::identical(view, "model")) selected_model() else NULL
      pest_key <- if (is.null(model)) "" else model$model_id[[1]]
      
      proxy <- leafletProxy("map") %>%
        clearGroup("Observations") %>%
        clearGroup("Suitability") %>%
        clearPopups() %>%
        removeControl("suitability_legend")
      
      if (base::identical(view, "occurrence")) {
        
        gbif <- pest_data()
        data <- gbif$data
        
        if (nrow(data) > 0) {
          
          observation_date <- if ("eventDate" %in% names(data)) {
            as.character(data$eventDate)
          } else {
            rep("Date unavailable", nrow(data))
          }
          observation_date[is.na(observation_date) | !nzchar(observation_date)] <- "Date unavailable"

          record_type <- if ("basisOfRecord" %in% names(data)) {
            gsub("_", " ", tolower(as.character(data$basisOfRecord)))
          } else {
            rep("Record type unavailable", nrow(data))
          }

          locality <- if ("locality" %in% names(data)) {
            as.character(data$locality)
          } else {
            rep(NA_character_, nrow(data))
          }

          country <- if ("country" %in% names(data)) {
            as.character(data$country)
          } else {
            rep(NA_character_, nrow(data))
          }

          location_text <- ifelse(
            !is.na(locality) & nzchar(locality),
            paste0(locality, ", ", country),
            ifelse(
              !is.na(country) & nzchar(country),
              country,
              "Location unavailable"
            )
          )

          gbif_link <- if ("key" %in% names(data)) {
            paste0(
              "https://www.gbif.org/occurrence/",
              data$key
            )
          } else {
            rep("https://www.gbif.org/", nrow(data))
          }

          popup_content <- sprintf(
            paste0(
              "<div class='popup-species'>%s</div>",
              "<strong>Date:</strong> %s<br>",
              "<strong>Location:</strong> %s<br>",
              "<strong>Record type:</strong> %s<br>",
              "<strong>Source:</strong> GBIF<br>",
              "<a href='%s' target='_blank' rel='noopener noreferrer'>",
              "View GBIF record</a>"
            ),
            species,
            htmltools::htmlEscape(observation_date),
            htmltools::htmlEscape(location_text),
            htmltools::htmlEscape(record_type),
            gbif_link
          )

          map_longitudes <- data$decimalLongitude
          map_latitudes <- data$decimalLatitude
          if (!isTRUE(gbif$global)) {
            map_longitudes <- c(map_longitudes, 10.5, 24.5)
            map_latitudes <- c(map_latitudes, 55, 69.5)
          }
          proxy %>% fitBounds(
            min(map_longitudes) - 1, min(map_latitudes) - 1,
            max(map_longitudes) + 1, max(map_latitudes) + 1
          )

          proxy %>%
            addCircleMarkers(
              data = data,
              lng = ~decimalLongitude,
              lat = ~decimalLatitude,
              popup = popup_content,
              radius = 5,
              stroke = TRUE,
              weight = 1,
              color = "#4D326F",
              opacity = 1,
              fillColor = observation_color,
              fillOpacity = 0.95,
              group = "Observations",
              clusterOptions = markerClusterOptions(
                showCoverageOnHover = FALSE,
                spiderfyOnMaxZoom = TRUE,
                chunkedLoading = TRUE, chunkInterval = 100, chunkDelay = 25
              )
            )
          
        } else {
          
          proxy %>%
            addPopups(
              lng = 15,
              lat = 62,
              popup = if (isTRUE(gbif$error)) {
                paste(
                  "<strong>Observations unavailable</strong><br>",
                  "Live GBIF data could not be retrieved. Please try again later."
                )
              } else {
                paste(
                  "<strong>No observations found</strong><br>",
                  "No matching recent records were returned for the selected search region.",
                  "This does not establish that the species is absent."
                )
              },
              options = popupOptions(
                closeButton = FALSE
              )
            )
        }
      }
      
      if (base::identical(view, "model")) {
        proxy %>% fitBounds(10.5, 55.0, 24.5, 69.5)
        
        if (pest_key %in% names(suitability_rasters)) {
          
          suitability_raster <- suitability_rasters[[pest_key]]
          
          # Preserve release predictions; hide mapped inland water in the display.
          raster_sweden <- masked_display_raster(pest_key)

          is_spread <- base::identical(model$period_key[[1]], "future_spread")
          legend_limits <- if (is_spread) c(0, 0.30) else c(0, 1)
          legend_title <- if (is_spread)
            "Climate-model spread" else "Climate suitability"
          map_colors <- if (is_spread) {
            c("#F7FBFF", "#C6DBEF", "#6BAED6", "#2171B5", "#08306B")
          } else suitability_colors

          pal <- colorNumeric(
            palette = map_colors,
            domain = legend_limits,
            na.color = "transparent"
          )
          
          proxy %>%
            addRasterImage(
              raster_sweden,
              colors = pal,
              opacity = isolate(if (is.null(input$suitability_opacity)) 0.75 else input$suitability_opacity / 100),
              group = "Suitability",
              layerId = "suitability-raster",
              method = "ngb",
              project = TRUE
            ) %>%
            
            addLegend(
              layerId = "suitability_legend",
              pal = pal,
              values = legend_limits,
              title = HTML(
                paste0(
                  "<span class='legend-title'>",
                  legend_title,
                  "</span>",
                  "<em>",
                  species,
                  "</em>"
                )
              ),
              position = "bottomright",
              opacity = 0.9,
              labFormat = labelFormat(
                transform = identity,
                digits = if (is_spread) 2 else 1
              )
            )
          
        } else {
          
          proxy %>%
            addPopups(
              lng = 15,
              lat = 62,
              popup = paste(
                "<strong>Model unavailable</strong><br>",
                "Reviewed model output has not yet been packaged for this selection."
              ),
              options = popupOptions(
                closeButton = FALSE
              )
            )
        }
      }
    },
    ignoreInit = FALSE
  )
}

shinyApp(ui, server)
